class SKE {
    m : string = ""
    r : string = ""
}

function km(mj : SKE) : string {
    let mo : string = ""

    for (let om = 0; om < mj.m.length; om++) {
        mo = mj.m[om] + mj.r[om] + mo 
    }

    return mo
}

